mapper.select:
SELECT channel_id channelId, COUNT(*) childCount FROM t_channel_api WHERE channel_id IN
#{id}
GROUP BY channel_id

mapper.update:
UPDATE t_channel_api SET api_name=#{apiName}, description=#{description}, definition_json=#{definitionJson},
version=version+1, updated_by=#{updatedBy}, update_time=#{updateTime}
WHERE channel_api_id=#{row.channelApiId} AND version=#{row.version}
